'use strict';
// Phase 1a.4B r4: prepares a NEW isolated synthetic workspace from the audited r3 one. Copies files only: no adb, installs,
// dependency changes, database opens or compilation here.
// - Verifies r3 (attestation bf4a27c0…, APK f4ffd9d8…, pinned in docs/validacion-fase1a4b/r3/authorization/apk-identity.json)
//   and every prepared r3 file against its attestation.
// - Verifies the r4 inventory and that the checkout matches every r3 pin except the corrected derived 1a.3B probes
//   (scripts/phase1a4b/phase1a3bProbes.ts, regenerated by derive-probes.cjs: missing-table class).
// - Incorporates ONLY that harness correction: phase1a3bProbes.ts, rewritten exactly as r1 did ('../../src/' -> './src/').
//   Production, references (the five Node parts) and every other harness file stay byte-identical to r3.
// - Writes a new attestation (phase '1a.4B r4'); build/ is never copied, so no earlier APK can be reused.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const root = path.resolve(__dirname, '../../..');
const base = 'C:/sf-1a4b-r3-20261107';
const workspace = 'C:/sf-1a4b-r4-20261107';
const R3_ATTESTATION = 'bf4a27c0292c9832a86ad5d55180e0ec03bd760a30e8552c88ede485b85daf54';
const R3_APK = 'f4ffd9d8520cdd640be90f48031268040588f1bf2f060354c8e2562248696af5';
const PROBES = 'scripts/phase1a4b/phase1a3bProbes.ts';
const PROBES_SHA256 = '4883d7ef7cbf15514a692630b1c8d45b660c7ff9b9ccf0309a23940031e68af3';
const REFERENCE_SHA256 = '1faa219207d86d95f7b55f3e3446243d3d6194bbd974e7018089e7acce41bd1b';
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const read = (dir, file) => fs.readFileSync(path.join(dir, file));
if (process.argv.length !== 2) throw Error('No arguments authorized');
if (fs.existsSync(workspace)) throw Error('Destination must be new; no overwrite or cleanup');

const inventory = JSON.parse(read(root, 'docs/validacion-fase1a4b/r4/authorization/inputs.sha256.json'));
if (inventory.phase !== '1a.4B r4') throw Error('Not the r4 inventory');
for (const [name, hash] of Object.entries(inventory.sources)) {
  if (name.startsWith('.claude/') || name.startsWith('.codex/')) continue; // guards: owner-managed, never altered here
  if (sha(read(root, name)) !== hash) throw Error('Reviewed input changed since the r4 inventory: ' + name);
}
if (sha(read(root, PROBES)) !== PROBES_SHA256) throw Error('Not the corrected derived probes');
if (sha(read(root, 'docs/validacion-fase1a4b/node/results.json')) !== REFERENCE_SHA256) throw Error('1a.4B reference changed');

const identity = JSON.parse(read(root, 'docs/validacion-fase1a4b/r3/authorization/apk-identity.json'));
const attestation = read(base, 'source-fingerprints.json');
if (sha(attestation) !== R3_ATTESTATION || identity.attestationSha256 !== R3_ATTESTATION) throw Error('Unrecognized r3 attestation');
if (sha(read(base, 'android/app/build/outputs/apk/release/app-release.apk')) !== R3_APK || identity.sha256 !== R3_APK) throw Error('r3 APK mismatch');
const record = JSON.parse(attestation);
if (record.packageId !== 'com.smartfin.snapshot5b2.tests' || record.workspace !== base || record.phase !== '1a.4B r3') throw Error('r3 identity mismatch');
for (const name of Object.keys(record.hashes)) {
  if (name.includes('..') || path.isAbsolute(name)) throw Error('Invalid r3 path');
  if (sha(read(base, name)) !== record.hashes[name]) throw Error('r3 prepared source changed: ' + name);
}
const drift = Object.entries(record.originalHashes).filter(([name, hash]) => sha(read(root, name)) !== hash).map(([name]) => name);
if (JSON.stringify(drift) !== JSON.stringify([PROBES])) throw Error('Checkout differs from r3 beyond the derived probes: ' + drift.join(', '));

const excluded = new Set(['node_modules', 'build', '.gradle', '.cxx', '.git', '.codex', '.claude', '.agents', 'docs']);
fs.cpSync(base, workspace, {recursive: true, filter(file) {
  const parts = path.relative(base, file).split(path.sep);
  return !parts.some(part => excluded.has(part)) && !/\.(?:db|sqlite|sqlite3)(?:-|$)|\.jks$/i.test(file);
}});
fs.symlinkSync(path.join(root, 'node_modules'), path.join(workspace, 'node_modules'), 'junction');
const r3Hashes = {...record.hashes};
record.workspace = workspace;
record.phase = '1a.4B r4';
record.r3 = {attestationSha256: R3_ATTESTATION, apkSha256: R3_APK, workspace: base};

const rewrite = bytes => bytes.toString().replaceAll("'../../src/", "'./src/")
  .replaceAll("'../phase6b/probes'", "'./phase6bProbes'").replaceAll("'../phase1a2/probes'", "'./phase1a2Probes'");
const probes = rewrite(read(root, PROBES));
if (/jest\.|reverseActivePaymentAllocations: async|requireNoActiveInstallmentAllocations: async/.test(probes)) throw Error('Neutralization found');
if (!probes.includes('export function missingTableName(') || !probes.includes("check(editTerms === 'other: no such table: installment_allocations'"))
  throw Error('Missing-table class or the strict version 4 check is absent');
fs.writeFileSync(path.join(workspace, 'phase1a3bProbes.ts'), probes);
record.hashes['phase1a3bProbes.ts'] = sha(probes);
record.adaptations['phase1a3bProbes.ts'] = '1a.3B probes derived for 1a.4B (derive-probes.cjs: D6 guard, version 4 flows, r4 missing-table class)';
record.originalHashes[PROBES] = PROBES_SHA256;

for (const [name, hash] of Object.entries(r3Hashes))
  if (name !== 'phase1a3bProbes.ts' && (record.hashes[name] !== hash || sha(read(workspace, name)) !== hash)) throw Error('r3 file changed: ' + name);
if (Object.keys(record.hashes).length !== Object.keys(r3Hashes).length) throw Error('Unexpected added file');
const expected = JSON.parse(read(workspace, 'phase1a4bNodeExpected.json'));
if (expected.reversal.editAmount.observation.backupRevision !== 33 || expected.guards.deletePurchase.observation.backupRevision !== 25)
  throw Error('Corrected 1a.4B expectations missing');
const flows = JSON.parse(read(workspace, 'phase1a3bNodeExpected.json')).flows;
if (flows.version4Incompatible.outcome !== 'other: no such table: installment_allocations' || !flows.version5) throw Error('Flows reference changed');
const manual = read(workspace, 'src/modules/transactions/useCases/saveManualTransaction.ts').toString();
if (!manual.includes('await reverseActivePaymentAllocations(') || !manual.includes('await requireNoActiveInstallmentAllocations(') ||
    !manual.includes('await recordInitialInstallmentRevision('))
  throw Error('1a.4B or 1a.4A step missing from the carried production code');
const walk = dir => fs.readdirSync(path.join(workspace, dir), {withFileTypes: true})
  .flatMap(entry => entry.isDirectory() ? walk(dir + '/' + entry.name) : [dir + '/' + entry.name]);
const users = walk('src').filter(file => /\.(tsx?|jsx?)$/.test(file) && /extraordinaryInstallmentPayment/i.test(read(workspace, file).toString()));
if (JSON.stringify(users) !== JSON.stringify(['src/modules/creditCards/useCases/extraordinaryInstallmentPayment.ts']))
  throw Error('The 1a.4B use case is referenced from production code: ' + users.join(', '));
const stillMismatched = Object.entries(record.originalHashes).filter(([name, hash]) => sha(read(root, name)) !== hash);
if (stillMismatched.length) throw Error('Checkout differs from attestation: ' + stillMismatched.map(([name]) => name).join(', '));

const encoded = JSON.stringify(record, null, 2);
fs.writeFileSync(path.join(workspace, 'source-fingerprints.json'), encoded);
fs.writeFileSync(path.join(workspace, 'android/app/src/main/assets/phase5b2-source-fingerprints.json'), encoded);
console.log(JSON.stringify({workspace, packageId: record.packageId, phase: record.phase, attestedFiles: Object.keys(record.hashes).length,
  changedFromR3: ['phase1a3bProbes.ts'], attestationSha256: sha(encoded), apkBuilt: false,
  expectations: {editAmount: 33, deletePurchase: 25, flowsVersion4: flows.version4Incompatible.outcome}}, null, 1));
